type plexLoginClient interface {
	Login(context.Context) (plexauth.LoginResult, error)
	User(context.Context, string) (plexauth.User, error)
}

type plexLoginOutcome struct {
	Username string
	PlexID   int
}

func completePlexLogin(ctx context.Context, configPath string, client plexLoginClient) (plexLoginOutcome, error) {
	login, err := client.Login(ctx)
	if err != nil {
		return plexLoginOutcome{}, err
	}
	if login.Token == "" {
		return plexLoginOutcome{}, fmt.Errorf("Plex authorization completed without an access token")
	}
	user, err := client.User(ctx, login.Token)
	if err != nil {
		return plexLoginOutcome{}, fmt.Errorf("verify Plex access token: %w", err)
	}
	if user.ID == 0 || user.Username == "" {
		return plexLoginOutcome{}, fmt.Errorf("Plex token verification returned an incomplete account")
	}
	cfg, err := config.Load(configPath)
	if err != nil {
		return plexLoginOutcome{}, err
	}
	if err := cfg.SaveCredential(login.Token); err != nil {
		return plexLoginOutcome{}, err
	}
	return plexLoginOutcome{Username: user.Username, PlexID: user.ID}, nil
}

func newAuthLoginCmd(flags *rootFlags) *cobra.Command {
	var launch bool
	var timeout time.Duration
	cmd := &cobra.Command{
		Use:         "login",
		Short:       "Authorize with Plex and save a verified access token",
		Example:     "  plexctl-pp-cli auth login\n  plexctl-pp-cli auth login --launch",
		Args:        cobra.NoArgs,
		Annotations: map[string]string{"mcp:hidden": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if flags.noInput {
				return usageErr(fmt.Errorf("auth login requires browser approval; re-run without --no-input"))
			}
			client := plexauth.New("https://plex.tv", "plexctl-pp-cli", nil)
			client.Timeout = timeout
			client.OnPIN = func(authorizeURL string) {
				fmt.Fprintln(cmd.OutOrStdout(), "Open this Plex authorization URL and approve the sign-in:")
				fmt.Fprintln(cmd.OutOrStdout(), authorizeURL)
				if launch {
					if err := openSetupURL(authorizeURL); err != nil {
						fmt.Fprintf(cmd.ErrOrStderr(), "could not open browser automatically: %v\n", err)
					}
				}
			}
			ctx, cancel := context.WithTimeout(cmd.Context(), timeout)
			defer cancel()
			outcome, err := completePlexLogin(ctx, flags.configPath, client)
			if err != nil {
				return authErr(err)
			}
			if flags.asJSON {
				return printJSONFiltered(cmd.OutOrStdout(), map[string]any{"authorized": true, "stored": true, "account": outcome.Username, "plex_id": outcome.PlexID, "credentials_path": credentialSavePath(nil)}, flags)
			}
			fmt.Fprintf(cmd.OutOrStdout(), "Plex authorization verified and stored for %s.\n", outcome.Username)
			return nil
		},
	}
	cmd.Flags().BoolVar(&launch, "launch", false, "Open the Plex authorization URL in your default browser")
	cmd.Flags().DurationVar(&timeout, "timeout", 10*time.Minute, "Maximum time to wait for browser authorization")
	return cmd
}

// newAuthSetupCmd prints concrete steps for getting a credential. Side-effect
// rule: print by default, --launch opt-in to open the URL, short-circuit when
// the verifier is running this in a sandboxed subprocess.
func newAuthSetupCmd(_ *rootFlags) *cobra.Command {
	var launch bool
	cmd := &cobra.Command{
		Use:     "setup",
		Short:   "Print steps for obtaining a credential (use --launch to open the URL)",
		Example: "  plexctl-pp-cli auth setup\n  plexctl-pp-cli auth setup --launch",
		RunE: func(cmd *cobra.Command, args []string) error {
			w := cmd.OutOrStdout()
			fmt.Fprintln(w, "Get a key at: https://...`")
			fmt.Fprintln(w, "")
			fmt.Fprintln(w, "Then set:")
			fmt.Fprintln(w, "  export PLEXCTL_USER_TOKEN=\"your-token-here\"")
			fmt.Fprintln(w, "  echo \"$TOKEN\" | plexctl-pp-cli auth set-token")
			if !launch {
				return nil
			}
			launchURL := "https://...`"
			if cliutil.IsVerifyEnv() {
				fmt.Fprintf(w, "would launch: %s\n", launchURL)
				return nil
			}
			if err := openSetupURL(launchURL); err != nil {
				fmt.Fprintf(cmd.ErrOrStderr(), "could not open browser automatically: %v\nopen this URL manually: %s\n", err, launchURL)
			}
			return nil
		},
	}
	cmd.Flags().BoolVar(&launch, "launch", false, "Open the setup URL in your default browser")
	return cmd
}

// openSetupURL opens url in the OS default browser. Per the side-effect rule,
// the caller short-circuits with cliutil.IsVerifyEnv() before this is reached.
func openSetupURL(url string) error {
	var c *exec.Cmd
	switch runtime.GOOS {
	case "darwin":
		c = exec.Command("open", url)
	case "linux":
		c = exec.Command("xdg-open", url)
	case "windows":
		c = exec.Command("rundll32", "url.dll,FileProtocolHandler", url)
	default:
		return fmt.Errorf("unsupported OS: %s", runtime.GOOS)
	}
	return c.Start()
}

func newAuthStatusCmd(flags *rootFlags) *cobra.Command {
	return &cobra.Command{
		Use:     "status",
		Short:   "Show authentication status",
		Example: "  plexctl-pp-cli auth status",
		RunE: func(cmd *cobra.Command, args []string) error {
			cfg, err := config.Load(flags.configPath)
			if err != nil {
				return configErr(err)
			}

			w := cmd.OutOrStdout()
			header := cfg.AuthHeader()
			authed := header != ""
			refusals := cfg.CredentialRefusalSummaries()
			credentialRefused := len(refusals) > 0
			// JSON envelope: {authenticated, verified, source, config}. When not
			// authenticated, write the envelope first then return authErr
			// so exit code carries the auth-failure signal.
			if flags.asJSON {
				out := map[string]any{
					"authenticated": authed,
					"verified":      false,
					"source":        cfg.AuthSource,
					"config":        cfg.Path,
				}
				if credentialRefused {
					out["credential_refused"] = true
					out["credential_refusals"] = refusals
				}
				if printErr := printJSONFiltered(w, out, flags); printErr != nil {
					return printErr
				}
				if !authed && credentialRefused {
					return authErr(cfg.CredentialRefusalError())
				}
				if !authed {
					return authErr(fmt.Errorf("no credentials configured"))
				}
				return nil
			}
			if !authed && credentialRefused {
				fmt.Fprintln(w, red("Credentials present but refused"))
				for _, refusal := range refusals {
					fmt.Fprintf(w, "  %s\n", refusal)
				}
				return authErr(cfg.CredentialRefusalError())
			}
			if !authed {
				fmt.Fprintln(w, red("Not authenticated"))
				fmt.Fprintln(w, "")
				fmt.Fprintln(w, "Set your token:")
				fmt.Fprintln(w, "  export PLEXCTL_USER_TOKEN=\"your-token-here\"")
				fmt.Fprintf(w, "  echo \"$TOKEN\" | plexctl-pp-cli auth set-token\n")
				return authErr(fmt.Errorf("no credentials configured"))
			}

			fmt.Fprintln(w, green("Credentials present (not verified)"))
			fmt.Fprintf(w, "  Source: %s\n", cfg.AuthSource)
			fmt.Fprintf(w, "  Config: %s\n", cfg.Path)
			return nil
		},
	}
}

func newAuthSetTokenCmd(flags *rootFlags) *cobra.Command {
	return &cobra.Command{
		Use:   "set-token",
		Short: "Save an API token to the credentials file",
		Long: "Save an API token to the credentials file.\n\n" +
			"The token is read from stdin so it never appears in process arguments or shell history.",
		Example: "  echo \"$TOKEN\" | plexctl-pp-cli auth set-token\n  plexctl-pp-cli auth set-token < token-file",
		Args:    cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			token, err := readSecretFromStdin(cmd.InOrStdin())
			if err != nil {
				return authErr(err)
			}

			cfg, err := config.Load(flags.configPath)
			if err != nil {
				return configErr(err)
			}

			// Clear any legacy auth_header so AuthHeader() falls through to
			// the newly-saved credential. Without this, a pre-existing
			// auth_header value (common after regenerate) shadows the saved
			// token and set-token silently has no effect. Silent clear (no
			// log line): a masked-tail variant could leak token bytes through
			// scripted dogfood that captures stderr.
			cfg.AuthHeaderVal = ""
			// api_key auth: AuthHeader() reads the env-var-derived field, not
			// AccessToken. Writing the token to AccessToken via SaveTokens
			// would persist the bytes but leave doctor reporting "not
			// configured" — the slot the header builder consults stays empty.
			if err := cfg.SaveCredential(token); err != nil {
				return configErr(fmt.Errorf("saving token: %w", err))
			}

			savePath := credentialSavePath(cfg)
			// JSON envelope: {saved, config_path, credentials_path}.
			if flags.asJSON {
				out := map[string]any{
					"saved":       true,
					"config_path": cfg.Path,
				}
				if !cfg.AgentcookieManagedByExternalStore() {
					out["credentials_path"] = savePath
				}
				return printJSONFiltered(cmd.OutOrStdout(), out, flags)
			}
			fmt.Fprintf(cmd.OutOrStdout(), "Token saved to %s\n", savePath)
			return nil
		},
	}
}

func credentialSavePath(cfg *config.Config) string {
	if cfg != nil && cfg.AgentcookieManagedByExternalStore() {
		return cfg.Path
	}
	if path, err := cliutil.CredentialsFilePath(); err == nil {
		return path
	}
	if cfg != nil {
		return cfg.Path
	}
	return ""
}

func newAuthLogoutCmd(flags *rootFlags) *cobra.Command {
	return &cobra.Command{
		Use:     "logout",
		Short:   "Clear stored credentials",
		Example: "  plexctl-pp-cli auth logout",
		RunE: func(cmd *cobra.Command, args []string) error {
			cfg, err := config.Load(flags.configPath)
			if err != nil {
				return configErr(err)
			}

			if err := cfg.ClearTokens(); err != nil {
				return configErr(fmt.Errorf("clearing tokens: %w", err))
			}

			// Identify which (if any) auth env var is still exported so the
			// JSON envelope and the human prose can both surface it.
			envStillSet := ""
			if envStillSet == "" && os.Getenv("PLEXCTL_USER_TOKEN") != "" {
				envStillSet = "PLEXCTL_USER_TOKEN"
			}

			// JSON envelope: {cleared: true, note?: "<env_var> env var is still set"}.
			if flags.asJSON {
				out := map[string]any{"cleared": true}
				if envStillSet != "" {
					out["note"] = envStillSet + " env var is still set"
				}
				return printJSONFiltered(cmd.OutOrStdout(), out, flags)
			}

			if envStillSet != "" {
				fmt.Fprintf(cmd.OutOrStdout(), "Config cleared. Note: %s env var is still set.\n", envStillSet)
				return nil
			}
			fmt.Fprintln(cmd.OutOrStdout(), "Logged out. Credentials cleared.")
			return nil
		},
	}
}
